private async void PasteImage_Click(object sender, RoutedEventArgs args)
{
    var package = Clipboard.GetContent();
    if (package.Contains(StandardDataFormats.Bitmap))
    {
        var imageReference = await package.GetBitmapAsync();
        using (var imageStream = await imageReference.OpenReadAsync())
        {
            var bitmapImage = new BitmapImage();
            bitmapImage.SetSource(imageStream);
            PastedImage.Source = bitmapImage;
        }
    }
}

private async void CopyFiles_Click(object sender, RoutedEventArgs args)
{
    var filePicker = new FileOpenPicker
    {
        ViewMode = PickerViewMode.List,
        FileTypeFilter = { "*" }
    };

    // Initialize the picker with the current window handle (required in WinUI 3)
    var hwnd = WinRT.Interop.WindowNative.GetWindowHandle(App.MainWindow);
    WinRT.Interop.InitializeWithWindow.Initialize(filePicker, hwnd);

    var storageItems = await filePicker.PickMultipleFilesAsync();
    if (storageItems.Count > 0)
    {
        var package = new DataPackage();
        package.SetStorageItems(storageItems);
        package.RequestedOperation = DataPackageOperation.Copy;
        Clipboard.SetContent(package);
    }
}

